\course{
  id={ai-ml-mastery},
  title={AI & Machine Learning Mastery},
  description={Learn the fundamentals of AI and ML from scratch},
  category={Artificial Intelligence},
  difficulty={Intermediate},
  estimatedHours={120}
}

\track{
  id={ml-fundamentals},
  title={Machine Learning Fundamentals},
  description={Master core ML concepts and algorithms},
  learningOutcomes={Build and deploy end-to-end ML models},
  careerOutcomes={ML Engineer, Data Scientist, AI Researcher},
  difficulty={Intermediate},

  \module{
    id={supervised-learning},
    title={Supervised Learning},
    description={Learn regression and classification algorithms},
    prerequisites={Basic Python, Linear Algebra},
    learningOutcomes={Implement linear regression, logistic regression, decision trees},
    estimatedHours={20},

    \lesson{
      id={intro-to-ml},
      title={Introduction to Machine Learning},

      \overview{
# Introduction to Machine Learning

Welcome to this comprehensive lesson on the fundamentals of Machine Learning!

## What is ML?

Machine Learning is a subset of AI that enables computers to learn from data without being explicitly programmed!
      }

      \video{
        type={youtube},
        url={https://youtube.com/watch?v=dQw4w9WgXcQ},
        title={ML Introduction Video}
      }

      \practice{
        id={first-ml-code},
        title={Your First Machine Learning Code},
        language={python},
        initialCode={print("Hello ML World!")},
        expectedOutput={Hello ML World!}
      }

      \quiz{
        id={ml-quiz-1}

        \question{
          text={What is Machine Learning?},
          options={{A=Magic}{B=AI that learns from data}{C=Just SQL}},
          correct={B},
          explanation={Machine Learning is a subset of AI that enables computers to learn from data without being explicitly programmed!}
        }

        \question{
          text={What is 2 + 2?},
          options={{A=3}{B=4}{C=5}},
          correct={B},
          explanation={Basic arithmetic!}
        }
      }

      \project{
        id={linear-regression-project},
        title={Build a Linear Regression Model from Scratch},
        description={Implement linear regression with gradient descent},
        difficulty={Medium},
        colabUrl={https://colab.research.google.com/drive/abc123},
        githubUrl={https://github.com/user/ml-project},
        instructions={1. Import necessary libraries
2. Load sample dataset
3. Implement gradient descent},
        expectedOutput={A trained linear regression model!}
      }

      \resource{
        type={link},
        title={Python Documentation},
        url={https://python.org}
      }
    }
  }
}

